<?php declare(strict_types=1); final class RateLimiter { public function __construct( private readonly string $path, private readonly string $secret ) {} public function hit(string $ip, int $limit = 2000, int $windowSeconds = 1, int $banSeconds = 300): int { $handle = fopen($this->path, 'c+'); if ($handle === false) { throw new RuntimeException('Rate limiter indisponível: falha ao abrir arquivo.'); } flock($handle, LOCK_EX); $raw = stream_get_contents($handle) ?: ''; $state = json_decode($raw, true); if (!is_array($state)) $state = []; $now = microtime(true); foreach ($state as $key => $entry) { if (($entry['last_seen'] ?? 0) < $now - 900) { unset($state[$key]); } } $key = hash_hmac('sha256', $ip, $this->secret); $entry = $state[$key] ?? [ 'window_started' => $now, 'count' => 0, 'banned_until' => 0, 'last_seen' => $now ]; if ((float) $entry['banned_until'] > $now) { $retry = (int) ceil((float) $entry['banned_until'] - $now); } else { if ($now - (float) $entry['window_started'] >= $windowSeconds) { $entry['window_started'] = $now; $entry['count'] = 0; } $entry['count']++; $retry = 0; if ((int) $entry['count'] > $limit) { $entry['banned_until'] = $now + $banSeconds; $retry = $banSeconds; } } $entry['last_seen'] = $now; $state[$key] = $entry; rewind($handle); ftruncate($handle, 0); fwrite($handle, json_encode($state)); fflush($handle); flock($handle, LOCK_UN); fclose($handle); @chmod($this->path, 0600); return $retry; } }